<template><FormSection :title="t('settings.proxy')"><label><input data-action="proxy-enable" type="checkbox" :checked="modelValue.enabled" @change="change('enabled',$event.target.checked)"> {{t('settings.proxy_enable')}}</label><label>HTTP <input aria-label="HTTP proxy" :disabled="!modelValue.enabled" :value="modelValue.http" @input="change('http',$event.target.value)"></label><label>HTTPS <input aria-label="HTTPS proxy" :disabled="!modelValue.enabled" :value="modelValue.https" @input="change('https',$event.target.value)"></label><label>No Proxy <input aria-label="No proxy" :disabled="!modelValue.enabled" :value="modelValue.noProxy" @input="change('noProxy',$event.target.value)"></label><StatusBadge v-if="result" :tone="result.success?'success':'error'">{{result.message}}</StatusBadge><template #actions><button data-action="proxy-test" type="button" @click="$emit('test')">{{t('settings.proxy_test')}}</button><button data-action="proxy-save" type="button" @click="$emit('save')">{{t('btn.save')}}</button></template></FormSection></template>
<script setup>import FormSection from '../FormSection.vue';import StatusBadge from '../StatusBadge.vue';const p=defineProps({modelValue:{type:Object,required:true},result:Object,t:{type:Function,required:true}});const e=defineEmits(['update:modelValue','test','save']);const change=(k,v)=>e('update:modelValue',{...p.modelValue,[k]:v});</script>
